function duplicateObject(){const o=selected();if(!o||currentScene().objects.length>=200)return;change(()=>{const copy=clone(o);copy.id=uid();copy.name=o.name+' copy';copy.x=clamp(o.x+1,bounds(currentScene()).minX,bounds(currentScene()).maxX);copy.z=clamp(o.z+.5,bounds(currentScene()).minZ,bounds(currentScene()).maxZ);currentScene().objects.push(copy);selectedId=copy.id;});renderInspector();renderLibraryContent();toast('A little more of a good thing.');}
function deleteObject(){const o=selected();if(!o)return;change(()=>{currentScene().objects=currentScene().objects.filter(x=>x.id!==o.id);selectedId=null;});renderInspector();renderLibraryContent();toast('Object removed. Undo brings it back.');}
function showBehaviors(){if(!selected()){toast('Choose an object first.');return;}showModal('A little bit of magic',`<h2>What should ${esc(selected().name)} do?</h2><p class="subtitle">Pick a behavior. Make it your own with the sliders.</p><div class="template-grid behavior-palette">${Object.entries(BEHAVIORS).filter(([key])=>!selected().behaviors.some(b=>b.type===key)).map(([key,b])=>`<button class="palette-item" data-add-behavior="${key}">${icon(b.icon)}<span><strong>${b.name}</strong><small>${b.hint}</small></span></button>`).join('')}</div>`);bindBehaviorCards($('#modal-content'));}
function startPath(){if(!selected())return;finishBuild(false);pathMode=true;tool='select';$('#path-done').hidden=false;$('#canvas-hint').textContent='Click the ground to add path points';$('#inspector').classList.remove('mobile-open');toast('Click places in your world, then press Done.');}
function finishPath(){pathMode=false;$('#path-done').hidden=true;$('#canvas-hint').innerHTML=icon('mouse')+'Two fingers to pan <b>·</b> Right-drag to orbit';renderInspector();}
function renderScenes(){$('#scene-count').textContent=project.scenes.length;$('#scene-strip').innerHTML=project.scenes.map((s,i)=>`<button class="scene-card ${i===sceneIndex?'active':''}" data-scene="${i}" title="Open ${esc(s.name)}">${i===sceneIndex?'<span class="scene-active-dot"></span>':''}<div class="scene-thumb ${s.theme}">${s.objects.filter(o=>o.visible).slice(0,3).map(o=>art(o.kind,o.color)).join('')}</div><div class="scene-caption"><b>${String(i+1).padStart(2,'0')}</b>${esc(s.name)}</div></button>`).join('')+`<button id="add-scene" class="new-scene">${icon('plus')}New scene</button>`;$$('[data-scene]').forEach(b=>b.onclick=()=>{if(session)return;finishPath();finishBuild(false);sceneIndex=Number(b.dataset.scene);selectedId=currentScene().objects[0]?.id||null;renderer.configure(project.camera);renderer.setScene(currentScene(),project.assets);renderer.selected=selectedId;renderer.path=selected()?.path||[];renderAll();});$('#add-scene').onclick=()=>{if(project.scenes.length>=30){toast('This project has reached 30 scenes.');return;}change(()=>{project.scenes.push(scene('A new world','forest',[object('hero',-3,2)]));sceneIndex=project.scenes.length-1;selectedId=currentScene().objects[0].id;});renderAll();toast('A new chapter begins.');};}
function showModal(eyebrow,html){$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function showTemplates(){showModal('A SMALL START. A BIG ADVENTURE.',`<h2>What will you make?</h2><p class="subtitle">Start with a tiny game. Change everything. Make it yours.</p><div class="template-grid">${TEMPLATES.map(t=>`<button class="template-card" data-template="${t.id}"><div class="template-art" style="--template-color:${t.color}44">${(t.id==='quest'?['tree','hero','crystal']:t.id==='shooter'?['ship','slime']:t.id==='racing'?['car','crystal']:t.id==='story'?['npc','portal']:t.id==='platformer'?['hero','crystal']:['sparkles']).map(k=>art(k,ASSETS.find(a=>a.kind===k)?.color||t.color)).join('')}</div><div class="template-content"><span><strong>${t.name}</strong><small>${t.tag} · ${t.mode.toUpperCase()}</small></span>${icon('chevron')}</div></button>`).join('')}</div><p class="dialog-note">Your current project stays in My projects.</p>`);$$('[data-template]').forEach(b=>b.onclick=async()=>{if(switching)return;switching=true;$$('[data-template]').forEach(x=>x.disabled=true);try{if(!await saveNow())return;activateProject(makeProject(b.dataset.template));modal.close();toast('Fresh game, fresh rules. Press Play!');}finally{switching=false;$$('[data-template]').forEach(x=>x.disabled=false);}});}
async function showProjects(){await saveNow();let projects=[];try{projects=await allProjects();}catch{}showModal('YOUR LITTLE COLLECTION',`<h2>My projects</h2><label class="field-label" for="project-name">This project’s name</label><div class="inline-row"><input id="project-name" class="text-input" value="${esc(project.name)}" maxlength="60"><button id="rename-project" class="button">${icon('check')}Save</button></div><div style="margin-top:20px">${projects.map(p=>`<button class="project-row" data-open-project="${esc(p.id)}">${icon(TEMPLATES.find(t=>t.id===p.genre)?.icon||'gamepad')}<span><strong>${esc(p.name)}</strong><small>${p.scenes.length} scene${p.scenes.length===1?'':'s'} · ${p.mode.toUpperCase()} · ${new Date(p.updated).toLocaleDateString()}</small></span>${icon('chevron','chev')}</button>`).join('')}</div><div class="modal-actions"><button id="import-project-modal" class="button">${icon('download')}Open project file</button><button id="new-project-modal" class="button primary">${icon('plus')}New game</button></div><p class="dialog-note">Projects are saved in this browser. Export a project file to keep a backup or move it to another device.</p>`);
 $('#rename-project').onclick=()=>{const name=$('#project-name').value.trim();if(!name)return;change(()=>project.name=name,false);toast('Project renamed');showProjects();};$$('[data-open-project]').forEach(b=>b.onclick=()=>{const p=projects.find(p=>p.id===b.dataset.openProject);if(!p)return;activateProject(validateProject(p));modal.close();});$('#import-project-modal').onclick=()=>$('#project-input').click();$('#new-project-modal').onclick=showTemplates;
}
function showSceneSettings(){const s=currentScene();showModal('EVERY WORLD HAS A STORY',`<h2>Your scene</h2><div class="scene-settings-grid"><div><label class="field-label" for="scene-name">Scene name</label><input id="scene-name" class="text-input" value="${esc(s.name)}" maxlength="50"></div><div><label class="field-label" for="scene-transition">Enter with</label><select id="scene-transition"><option value="fade" ${s.transition==='fade'?'selected':''}>A gentle fade</option><option value="slide" ${s.transition==='slide'?'selected':''}>A little slide</option><option value="none" ${s.transition==='none'?'selected':''}>Straight in</option></select></div></div><label class="field-label" for="story-title">Story title</label><input id="story-title" class="text-input" value="${esc(s.story.title)}" maxlength="100"><label class="field-label" for="story-text">What happens here?</label><textarea id="story-text" maxlength="1500">${esc(s.story.text)}</textarea><label class="field-label">Choices → where they go</label><div id="story-choices"></div><button id="add-story-choice" class="quiet-button">${icon('plus')}Add a choice</button><p class="dialog-note">Friends and story buttons open this story. In an adventure starter, it opens when the scene begins.</p><div class="modal-actions"><button id="duplicate-scene" class="button">${icon('copy')}Duplicate</button><button id="delete-scene" class="button danger" ${project.scenes.length<2?'disabled':''}>${icon('trash')}Delete</button><button id="save-scene-settings" class="button primary">${icon('check')}Done</button></div>`);
 let choices=clone(s.story.choices);const readChoices=()=>{choices=$$('#story-choices .choice-editor').map(row=>({text:row.querySelector('input').value||'Continue',target:row.querySelector('select').value}));};
 function choicesUI(){$('#story-choices').innerHTML=choices.map((c,i)=>`<div class="choice-editor"><input class="text-input" aria-label="Choice ${i+1} text" value="${esc(c.text)}" maxlength="80"><select aria-label="Choice ${i+1} destination">${[{id:'close',name:'Keep exploring'},{id:'next',name:'Next scene'},...project.scenes].map(t=>`<option value="${esc(t.id)}" ${c.target===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="icon-button" data-remove-choice="${i}" aria-label="Remove choice ${i+1}">${icon('close')}</button></div>`).join('');$$('[data-remove-choice]').forEach(b=>b.onclick=()=>{readChoices();if(choices.length>1)choices.splice(Number(b.dataset.removeChoice),1);choicesUI();});$('#add-story-choice').disabled=choices.length>=4;}
 choicesUI();$('#add-story-choice').onclick=()=>{readChoices();if(choices.length<4)choices.push({text:'A new possibility',target:'close'});choicesUI();};
 $('#save-scene-settings').onclick=()=>{readChoices();change(()=>{s.name=$('#scene-name').value.trim()||'My world';s.transition=$('#scene-transition').value;s.story={title:$('#story-title').value||'My story',text:$('#story-text').value,choices};},false);modal.close();toast('Your story is ready to play.');};
 $('#duplicate-scene').onclick=()=>{if(project.scenes.length>=30)return;change(()=>{const copy=clone(s);copy.id=uid();copy.name=s.name+' copy';copy.objects.forEach(o=>o.id=uid());project.scenes.push(copy);sceneIndex=project.scenes.length-1;selectedId=copy.objects[0]?.id||null;});renderAll();modal.close();};
 $('#delete-scene').onclick=()=>{if(project.scenes.length<2)return;change(()=>{const removed=s.id;project.scenes.splice(sceneIndex,1);project.scenes.forEach(s=>s.story.choices.forEach(c=>{if(c.target===removed)c.target='next';}));sceneIndex=clamp(sceneIndex,0,project.scenes.length-1);selectedId=currentScene().objects[0]?.id||null;});renderAll();modal.close();toast('Scene removed. Undo brings it back.');};
}
function showHelp(){showModal('BIG IDEAS START WITH A LITTLE PLAY',`<h2>Your first game, in three little steps.</h2><div class="help-steps"><div class="help-step">${icon('box')}<div><strong>1. Drop something in.</strong><p>Drag an asset into your world. Or click one to add it. Your own images work too.</p></div></div><div class="help-step">${icon('bolt')}<div><strong>2. Give it a little magic.</strong><p>Pick an object, then add a behavior. Make it follow, wander, sparkle, or do what you say.</p></div></div><div class="help-step">${icon('play')}<div><strong>3. Play your idea.</strong><p>Press Play. Move with arrows or WASD. Space jumps or shoots. E talks to a friend.</p></div></div></div><div class="pill-note">${icon('heart')}Every idea is worth trying. Undo is always here for you.</div><p class="dialog-note">Drag objects to move them. Two fingers or H to pan. Pinch to zoom. Right-drag to orbit in 3D.<br>Ctrl/⌘ Z: undo · Ctrl/⌘ D: duplicate · Delete: remove · Enter: play · Esc: stop.<br>On a small screen, tap an object again to open its settings.</p><button id="help-start" class="button primary wide-button">Let’s make something ${icon('sparkles')}</button>`);$('#help-start').onclick=()=>modal.close();}
function showExport(){showModal('MADE BY YOU. READY TO PLAY.',`<h2>Let your game out into the world.</h2><p class="subtitle">A little file. Your whole imagination inside.</p><button class="export-card" id="export-html">${icon('gamepad')}<span><strong>Playable game</strong><small>One HTML file. Open it in a browser.<br>Includes every scene, image, sound, and behavior.</small></span>${icon('chevron','chev')}</button><button class="export-card" id="export-project">${icon('folder')}<span><strong>Editable project</strong><small>Keep a backup, move devices, or keep creating later.</small></span>${icon('chevron','chev')}</button>${selected()?`<button class="export-card" id="export-asset">${icon('image')}<span><strong>Save ${esc(selected().name)} as an image</strong><small>A PNG for your next idea.</small></span>${icon('chevron','chev')}</button>`:''}<p class="dialog-note">Games run in a browser, including offline. This exports a browser game, not a phone app or console game.</p>`);
 $('#export-project').onclick=()=>{download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),slug(project.name)+'.soulcode');toast('Project backup downloaded.');};$('#export-html').onclick=exportGame;if($('#export-asset'))$('#export-asset').onclick=exportAsset;
}
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'my-game';
async function exportGame(){const b=$('#export-html');b.disabled=true;try{const response=await fetch('./player.js');if(!response.ok)throw Error('Player file is missing');const code=(await response.text()).replace(/<\/script/gi,'<\\/script'),data=JSON.stringify(project).replace(/</g,'\\u003c');const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(project.name)} · Soulcode</title><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:system-ui;color:#e5f7ff;background:#101e28}#game{position:absolute;inset:0;background:radial-gradient(ellipse,#27444d,#101b26);touch-action:none}canvas{display:block;width:100%;height:100%}#start-screen{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 40%,#234557,#0f1b28)}#start-screen[hidden]{display:none}.welcome{max-width:480px;text-align:center;padding:32px}.welcome .spark{font-size:64px;color:#74e4ff}.welcome h1{font-size:44px;letter-spacing:-2px;margin:20px 0}.welcome p{color:#a0bdcc;font-size:14px;line-height:1.7}button{cursor:pointer;background:#64dff4;border:0;border-radius:12px;color:#153c4b;font:700 16px system-ui;padding:14px 35px}#mute-game{position:fixed;right:20px;bottom:14px;padding:7px 10px;background:#193744c9;color:#abd9e8;font-size:10px;z-index:30}.credit{position:absolute;left:20px;bottom:18px;color:#7092a8;font-size:10px;z-index:20}.scene-fade canvas{animation:fade .7s}.scene-slide canvas{animation:slide .7s}@keyframes fade{from{opacity:0}to{opacity:1}}@keyframes slide{from{opacity:0;transform:translateX(50px)}to{opacity:1;transform:none}}</style></head><body><main id="game"></main><div id="start-screen"><div class="welcome"><span class="spark">✦</span><h1 id="game-name">${esc(project.name)}</h1><p>A little world, made with Soulcode.</p><button id="start-play">Let’s play →</button><p>Arrow keys / WASD · Space · E<br>Touch controls on phones and tablets</p></div></div><span class="credit">made with soulcode.</span><button id="mute-game">Sound ${project.sound?'on':'off'}</button><script type="application/json" id="soulcode-project">${data}</script><script>${code}</script></body></html>`;download(new Blob([html],{type:'text/html'}),slug(project.name)+'.html');toast('Your game is ready. Open the downloaded HTML file to play.');}catch(e){toast('Could not export the game. '+e.message);}finally{b.disabled=false;}}
async function exportAsset(){const o=selected();if(!o)return;const im=new Image();im.src=o.kind==='image'?(project.assets.find(a=>a.id===o.assetId)?.src||''):'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(art(o.kind,o.color));try{await im.decode();const c=document.createElement('canvas');c.width=o.kind==='image'?im.naturalWidth:512;c.height=o.kind==='image'?im.naturalHeight:512;c.getContext('2d').drawImage(im,0,0,c.width,c.height);c.toBlob(blob=>{if(blob){download(blob,slug(o.name)+'.png');toast('Your asset is ready.');}},'image/png');}catch{toast('This image could not be exported.');}}
async function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
async function importAssets(files,pos){if(session){toast('Stop playing to add assets.');return;}const incoming=[...files];if(incoming.length===1&&/\.(soulcode|json)$/i.test(incoming[0].name)){await importProject(incoming[0]);return;}let added=[];for(const f of incoming){if(project.assets.length+added.length>=60){toast('You can keep up to 60 uploaded assets in a project.');break;}if(f.size>8*1024*1024){toast(`${f.name} is too large. Try a file smaller than 8 MB.`);continue;}let kind,src,width=1,height=1;
 try{if(/^image\/(png|jpeg|webp|gif)$/.test(f.type)){kind='image';const data=await fileData(f),im=new Image();im.src=data;await im.decode();const c=document.createElement('canvas'),ratio=Math.min(1,1024/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*ratio));c.height=Math.max(1,Math.round(im.height*ratio));c.getContext('2d').drawImage(im,0,0,c.width,c.height);src=c.toDataURL('image/png');width=c.width;height=c.height;}
 else if(/^audio\//.test(f.type)||/\.(mp3|wav|ogg|m4a)$/i.test(f.name)){kind='audio';src=await fileData(f);if(!src.startsWith('data:audio/')){const ext=f.name.split('.').pop().toLowerCase();src=src.replace(/^data:[^;,]*;/,`data:audio/${({mp3:'mpeg',wav:'wav',ogg:'ogg',m4a:'mp4'})[ext]||'mpeg'};`);}const audio=new Audio();if(f.type&&!audio.canPlayType(f.type)){toast(`${f.name}: this browser may not play that audio format.`);}}
 else{toast('Try a PNG, JPG, WebP, GIF, MP3, WAV, OGG, or M4A file.');continue;}
 const total=[...project.assets,...added].reduce((n,a)=>n+a.src.length,0)+src.length;if(total>28*1024*1024){toast('This project’s assets are full. Try smaller image or sound files.');continue;}added.push({id:uid(),kind,name:f.name.slice(0,60),src,width,height});
 }catch{toast(`Could not open ${f.name}. Try another file.`);}}
 if(added.length){finishBuild(false);finishPath();change(()=>{project.assets.push(...added);if(pos){const image=added.find(a=>a.kind==='image');if(image&&currentScene().objects.length<200){const o=object('image',pos.x,project.camera.preset==='side'?.5:pos.z,{y:pos.y||0,assetId:image.id,name:image.name});currentScene().objects.push(o);selectedId=o.id;}}});if(added.some(a=>a.kind==='image')){category='Yours';panel='assets';libraryTab='library';}else panel='sounds';renderAll();toast(`${added.length} ${added.length===1?'asset':'assets'} added. Yours to play with.`);}
}
async function importProject(file){if(file.size>64*1024*1024){toast('Choose a project file smaller than 64 MB.');return;}try{const p=validateProject(JSON.parse(await file.text()));if(!await saveNow())return;p.id=uid();p.updated=Date.now();activateProject(p);modal.close();toast('Welcome back to your world.');}catch(e){toast(e.message||'This project could not be opened.');}}
function startGame(){if(session){stopGame();return;}if(!currentScene().objects.some(o=>o.visible&&(has(o,'control')||has(o,'drive')))){toast('Add a character with “You control it” or “Drive” to play.');return;}finishPath();finishBuild(false);previewAudio?.pause();modal.close();document.body.classList.add('playing');$('#library').inert=true;$('#inspector').inert=true;$('.tool-rail').inert=true;$('.scenes-panel').inert=true;$('#play-button').innerHTML=icon('stop')+'<span>Stop</span>';$('#pause-button').hidden=false;$('#stop-button').hidden=false;$('#status-text').textContent='Your world is alive. Go explore.';session=new GameSession({host:viewport,project:clone(project),sceneIndex,renderer,onStop:stopGame});$('#viewport').focus();}
function stopGame(){if(!session)return;session.destroy();session=null;document.body.classList.remove('playing');$('#library').inert=false;$('#inspector').inert=false;$('.tool-rail').inert=false;$('.scenes-panel').inert=false;$('#play-button').innerHTML=icon('play')+'<span>Play</span><kbd>↵</kbd>';$('#pause-button').hidden=true;$('#stop-button').hidden=true;$('#pause-button').innerHTML=icon('pause');$('#status-text').textContent='A little studio for big imaginations';renderer.setScene(currentScene(),project.assets);renderer.selected=selectedId;renderer.path=selected()?.path||[];}
function activateProject(next){stopGame();previewAudio?.pause();clearTimeout(saveTimer);saveRevision++;project=next;sceneIndex=0;selectedId=currentScene().objects[0]?.id||null;history=[];future=[];$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool==='select'));viewport.style.cursor='default';panel='assets';libraryTab='library';category='All';search='';pathMode=false;buildMode=false;tool='select';terrainDirty=false;drag=null;pointers.clear();gesture=null;Object.assign(brush,{tool:'floor',shape:'cube',tile:currentScene().map.tileset,layer:0,erase:false});$('#path-done').hidden=true;document.body.classList.remove('focus','shelf-hidden');$('#library').style.display='';$('#library').classList.remove('mobile-open');$('#inspector').classList.remove('mobile-open');renderer?.destroy();renderer=null;resetRenderer();renderAll();updateZoom();saveSoon();}
function finishBuild(rerender=true){buildMode=false;if(renderer)renderer.brushCell=null;$('#canvas-hint').innerHTML=icon('hand')+'Two fingers to pan <b>·</b> Right-drag to orbit';if(rerender){setPanel('assets');toast('Back to your characters.');}}
function spriteStudio(asset=null){if(session)return;openSpriteStudio({showModal,asset,onSave:data=>{if(!data.id&&project.assets.length>=60){toast('Your asset shelf is full.');return;}const total=project.assets.filter(a=>a.id!==data.id).reduce((n,a)=>n+a.src.length,0)+data.src.length;if(total>28*1024*1024){toast('Your asset shelf is full. Export a backup and use smaller files.');return;}change(()=>{if(data.id){const index=project.assets.findIndex(a=>a.id===data.id);project.assets[index]=data;}else{data.id=uid();project.assets.push(data);}});finishBuild(false);finishPath();panel='assets';libraryTab='library';category='Yours';search='';renderAll();modal.close();toast('Your sprite is ready. Drop it into your world.');}});}
let drag=null,gesture=null,terrainDirty=false;const pointers=new Map();
function touchPair(){return [...pointers.values()].filter(p=>p.type==='touch').slice(0,2);}
function gestureState(){const a=touchPair();return a.length<2?null:{x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2,d:Math.max(5,Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y))};}
function paintAt(e){const cell=renderer.terrainCell(e.clientX,e.clientY,brush);renderer.brushCell=cell;renderer.brushHeight=brush.tool==='wall'?3:brush.tool==='floor'?.05:SHAPES[brush.shape].height;if(!drag)return;const key=`${cell.x},${cell.y},${cell.z}`;if(drag.cell===key)return;const column=renderer.mode==='3d'&&brush.layer===0&&brush.tool!=='floor'?`${cell.x},${cell.z}`:key;drag.visited??=new Set();if(drag.visited.has(column))return;drag.visited.add(column);if(!drag.mutated){checkpoint();drag.mutated=true;}const previous=drag.lastCell||cell,steps=Math.min(80,Math.max(Math.abs(cell.x-previous.x),Math.abs(cell.z-previous.z),Math.abs(cell.y-previous.y)));let any=false;for(let i=0;i<=steps;i++){const f=steps?i/steps:1;any=paintCell(currentScene().map,{x:Math.round(previous.x+(cell.x-previous.x)*f),z:Math.round(previous.z+(cell.z-previous.z)*f),y:Math.round(previous.y+(cell.y-previous.y)*f)},brush)||any;}if(any)terrainDirty=true;else if(currentScene().map.blocks.length>=MAX_BLOCKS&&!brush.erase)toast('4,096 blocks in this scene. A new scene gives you more room.');drag.cell=key;drag.lastCell=cell;}
viewport.addEventListener('contextmenu',e=>{if(!allowContextMenu())e.preventDefault();});
viewport.addEventListener('pointerdown',e=>{if(session||e.target.closest('button'))return;e.preventDefault();viewport.focus();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,type:e.pointerType});viewport.setPointerCapture(e.pointerId);
 if(touchPair().length===2){if(drag?.mutated){const prior=history.pop();if(prior){project=prior.project;sceneIndex=prior.sceneIndex;selectedId=prior.selectedId;resetRenderer();renderAll();}}drag=null;terrainDirty=false;gesture=gestureState();renderer.brushCell=null;return;}
 const hit=renderer.hit(e.clientX,e.clientY,currentScene().objects),action=e.button===1||tool==='pan'||e.shiftKey?'pan':e.button===2||tool==='orbit'||e.altKey?'orbit':buildMode?'build':pathMode?'path':'select';
 drag={id:action==='select'?hit:null,action,startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false,mutated:false,oldSelected:selectedId,time:performance.now(),touch:e.pointerType==='touch'};
 if(hit&&action==='select'){selectObject(hit);const o=selected(),p=renderer.screenToWorld(e.clientX,e.clientY,o.y);drag.offset={x:o.x-p.x,y:o.y-p.y,z:o.z-p.z};}
 if(action==='build'&&!drag.touch)paintAt(e);
});
viewport.addEventListener('pointermove',e=>{if(session)return;if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,type:e.pointerType});const pair=gestureState();if(pair){if(gesture){renderer.panPixels(pair.x-gesture.x,pair.y-gesture.y);renderer.setZoom(renderer.zoom*pair.d/gesture.d);updateZoom();}gesture=pair;return;}
 if(buildMode&&!drag){renderer.brushCell=renderer.terrainCell(e.clientX,e.clientY,brush);renderer.brushHeight=brush.tool==='wall'?3:brush.tool==='floor'?.05:SHAPES[brush.shape].height;}
 if(!drag||gesture)return;const dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;if(drag.touch&&performance.now()-drag.time<100)return;
 if(!drag.moved&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4){drag.moved=true;if(drag.id&&!drag.mutated){checkpoint();drag.mutated=true;}}
 if(drag.moved){if(drag.action==='orbit')renderer.orbit(dx,dy);else if(drag.action==='pan')renderer.panPixels(dx,dy);else if(drag.action==='build')paintAt(e);else if(drag.id){const o=selected(),point=renderer.screenToWorld(e.clientX,e.clientY,o.y),b=bounds(currentScene(),.1);o.x=clamp(point.x+drag.offset.x,b.minX,b.maxX);if(project.camera.preset==='side')o.y=clamp(point.y+drag.offset.y,0,20);else o.z=clamp(point.z+drag.offset.z,b.minZ,b.maxZ);updateTop();}}
 drag.lastX=e.clientX;drag.lastY=e.clientY;
});
function pointerEnd(e,cancelled=false){pointers.delete(e.pointerId);if(gesture){if(!pointers.size)gesture=null;drag=null;return;}if(!drag)return;
 if(!cancelled&&!drag.moved){if(drag.action==='build')paintAt(e);else if(drag.action==='path'){const p=renderer.screenToWorld(e.clientX,e.clientY);change(()=>{const o=selected();if(o){o.path??=[];if(o.path.length<40)o.path.push(p);}},false);}else if(drag.action==='select'){if(drag.id&&drag.oldSelected===drag.id)$('#inspector').classList.add('mobile-open');else if(!drag.id)selectObject(null);}}
 if(drag.mutated){changed(false);renderInspector();if(panel==='build')renderLibrary();}drag=null;
}
viewport.addEventListener('pointerup',e=>pointerEnd(e));viewport.addEventListener('pointercancel',e=>pointerEnd(e,true));viewport.addEventListener('pointerleave',()=>{if(!drag)renderer.brushCell=null;});
viewport.addEventListener('wheel',e=>{if(session)return;e.preventDefault();if(e.ctrlKey||e.metaKey){renderer.setZoom(renderer.zoom*Math.exp(-e.deltaY*.007));updateZoom();}else if(e.shiftKey||Math.abs(e.deltaX)>1||(e.deltaMode===0&&Math.abs(e.deltaY)<50)){renderer.panPixels(-e.deltaX,-e.deltaY);}else{renderer.setZoom(renderer.zoom*(e.deltaY>0?.94:1.06));updateZoom();}},{passive:false});
viewport.addEventListener('dragover',e=>{if(session)return;e.preventDefault();viewport.classList.add('drop-highlight');e.dataTransfer.dropEffect='copy';});viewport.addEventListener('dragleave',()=>viewport.classList.remove('drop-highlight'));
viewport.addEventListener('drop',e=>{e.preventDefault();viewport.classList.remove('drop-highlight');if(session)return;const pos=renderer.placementPoint(e.clientX,e.clientY);if(e.dataTransfer.files.length){importAssets(e.dataTransfer.files,pos);return;}try{const d=JSON.parse(e.dataTransfer.getData('application/soulcode'));if(d.type==='asset'){finishBuild(false);addAsset(d.id,pos);}else if(d.type==='behavior'){const hit=renderer.hit(e.clientX,e.clientY,currentScene().objects);if(hit)selectObject(hit);addBehavior(d.id);}}catch{}});
function updateZoom(){$('#zoom-reset').innerHTML=Math.round(renderer.zoom*100)+'<span>%</span>';}
function bindUI(){hydrate();$$('[data-panel]').forEach(b=>b.onclick=()=>{if(session)return;$('#library').style.display='';setPanel(b.dataset.panel);});$('#modal-close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});$('#templates-button').onclick=showTemplates;$('#sprite-button').onclick=()=>spriteStudio();$('#camera-button').onclick=()=>{if(session)return;cameraDialog({project,showModal,change,slider,bindSlider,refresh:()=>{resetRenderer();renderAll();}});};$('#project-menu').onclick=showProjects;$('#projects-button').onclick=showProjects;$('#export-button').onclick=()=>{stopGame();showExport();};$('#help-button').onclick=showHelp;$('#play-button').onclick=startGame;$('#stop-button').onclick=stopGame;$('#pause-button').onclick=()=>{if(session){const paused=session.togglePause();$('#pause-button').innerHTML=icon(paused?'play':'pause');$('#pause-button').setAttribute('aria-label',paused?'Resume preview':'Pause preview');}};
 $('#scene-settings').onclick=showSceneSettings;$('#path-done').onclick=finishPath;$('#undo-button').onclick=()=>restore('undo');$('#redo-button').onclick=()=>restore('redo');
 $$('[data-mode]').forEach(b=>b.onclick=()=>{if(session||project.mode===b.dataset.mode)return;change(()=>{project.mode=b.dataset.mode;project.camera=cameraDefaults(project.mode==='2d'?'flat':'iso');},false);resetRenderer();updateTop();toast(`${project.mode.toUpperCase()} — same world, a new perspective.`);});$$('[data-tool]').forEach(b=>b.onclick=()=>{finishBuild(false);tool=b.dataset.tool;$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));viewport.style.cursor=tool==='orbit'||tool==='pan'?'grab':'default';});$('#grid-button').onclick=()=>{renderer.showGrid=!renderer.showGrid;$('#grid-button').classList.toggle('active',renderer.showGrid);$('#grid-button').setAttribute('aria-pressed',renderer.showGrid);};$('#focus-button').onclick=()=>{document.body.classList.toggle('focus');$('#focus-button').setAttribute('aria-pressed',document.body.classList.contains('focus'));};$('#zoom-in').onclick=()=>{renderer.setZoom(renderer.zoom+.1);updateZoom();};$('#zoom-out').onclick=()=>{renderer.setZoom(renderer.zoom-.1);updateZoom();};$('#zoom-reset').onclick=()=>{renderer.reset();updateZoom();};$('#sound-toggle').onclick=()=>{project.sound=!project.sound;session?.setMuted(!project.sound);updateTop();saveSoon();};
 $('#asset-input').onchange=e=>{importAssets(e.target.files);e.target.value='';};$('#project-input').onchange=e=>{if(e.target.files[0])importProject(e.target.files[0]);e.target.value='';};
 window.addEventListener('keydown',e=>{if(session||modal.open||e.target.matches('input,textarea,select'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();restore(e.shiftKey?'redo':'undo');}else if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();restore('redo');}else if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateObject();}else if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveNow().then(ok=>ok&&toast('Saved on this device.'));}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteObject();}else if(e.key==='Enter'){e.preventDefault();startGame();}else if(e.key==='Escape'){finishPath();$('#inspector').classList.remove('mobile-open');$('#library').classList.remove('mobile-open');}else if(e.key.toLowerCase()==='h')$('[data-tool="pan"]').click();else if(e.key.toLowerCase()==='v')$('[data-tool="select"]').click();});
 window.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});window.addEventListener('drop',e=>{if(e.dataTransfer.files.length)e.preventDefault();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){saveNow();previewAudio?.pause();}});
}
async function init(){try{const projects=await allProjects();let last;try{last=localStorage.getItem('soulcode-last');}catch{}const found=projects.find(p=>p.id===last);if(found){project=validateProject(found);selectedId=project.scenes[0].objects[0]?.id||null;}}catch{}resetRenderer();bindUI();renderAll();saveSoon();function loop(t){if(terrainDirty){terrainDirty=false;renderer.setTerrain(currentScene());}if(!session)renderer.draw(currentScene().objects,t/1000);requestAnimationFrame(loop);}requestAnimationFrame(loop);}
// Xbox One: the studio works there but is made for a mouse and keyboard. TV-size text (html.console-kit CSS), a note that
// can be hidden for good, and B (Escape) closes a dialog, the play preview or a path instead of leaving the page.
if(isConsole()){startConsoleKit({card:false});consoleNote();window.addEventListener('keydown',e=>{if(e.key!=='Escape'||!(session||modal.open||pathMode))return;e.preventDefault();if(modal.open&&!session)modal.close();},true);}
function consoleNote(){try{if(localStorage.getItem('soulcode-console-note'))return;}catch{}const note=document.createElement('div');note.className='console-note';note.setAttribute('role','note');const text=document.createElement('span');text.textContent='Soulcode works here, but it is at its best on a computer with a mouse and keyboard.';const ok=document.createElement('button');ok.type='button';ok.textContent='Got it';ok.onclick=()=>{note.remove();try{localStorage.setItem('soulcode-console-note','1');}catch{}};note.append(text,ok);document.body.append(note);}
init().catch(e=>{console.error(e);toast('The studio could not start. Reload to try again.');});
